function biggerSide(nums: number[]): number {
  const firstAtLeast = (t: number): number => {
    let lo = 0, hi = nums.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (nums[mid] < t) lo = mid + 1;
      else hi = mid;
    }
    return lo;
  };
  const neg = firstAtLeast(0);
  const pos = nums.length - firstAtLeast(1);
  return Math.max(neg, pos);
}

